const rows = items[0].json.value;

/* =========================================================
   CONFIG
========================================================= */
const SUMMARY_TITLE = "Daily EOD Summary";

/* =========================================================
   HELPERS
========================================================= */
function clean(value) {
  return (value || "").toString().trim();
}

function getDateKey(date) {
  return date.toISOString().split('T')[0];
}

function formatDisplayDate(dateString) {
  if (!dateString) return "";
  const d = new Date(dateString);
  if (isNaN(d)) return "";
  return d.toLocaleDateString('en-GB', {
    day: '2-digit',
    month: 'short',
    year: 'numeric'
  });
}

function getTodayDateKey() {
  return getDateKey(new Date());
}

function getSummaryDisplayDate() {
  return new Date().toLocaleDateString('en-GB', {
    day: '2-digit',
    month: 'long',
    year: 'numeric'
  });
}

/* =========================================================
   DATE LOGIC (Standard Dayshift Style: All checked today)
========================================================= */
const TARGET_DATE = getTodayDateKey();

/* =========================================================
   DATA STRUCTURES
========================================================= */
const rawGrouped = {};

/* =========================================================
   PROCESS SHAREPOINT DATA
========================================================= */
for (const row of rows) {
  const item = row.fields;
  if (!item) continue;

  const snapshotDate = clean(item.SnapshotDate).split('T')[0];
  if (snapshotDate !== TARGET_DATE) continue;

  // Using the new 'BucketValue' column
  const bucket = clean(item.BucketValue).toUpperCase();
  if (bucket !== "SOD" && bucket !== "EOD" && bucket !== "BLOCKED") continue;

  const employee = clean(item.AssignedTo).replace(/,\s*$/, '') || "Unassigned";
  const title = clean(item.Title) || "Untitled Task";
  const notes = clean(item.Notes);
  const dueDate = formatDisplayDate(item.DueDate);
  const delayed = clean(item.Is_x0020_Delayed).toLowerCase().includes("yes");

  const taskObject = { title, notes, dueDate, delayed };

  if (!rawGrouped[employee]) {
    rawGrouped[employee] = { sod: [], eod: [], blocked: [] };
  }

  if (bucket === "SOD") rawGrouped[employee].sod.push(taskObject);
  if (bucket === "EOD") rawGrouped[employee].eod.push(taskObject);
  if (bucket === "BLOCKED") rawGrouped[employee].blocked.push(taskObject);
}

/* =========================================================
   COMPUTE COMPLETED VS IN-PROGRESS (EOD UPDATES)
========================================================= */
const finalEmployees = {};

for (const employee in rawGrouped) {
  const { sod, eod, blocked } = rawGrouped[employee];

  const completed = [];
  const inProgress = [];

  // 1. All EOD tasks are Completed
  for (const eodTask of eod) {
    completed.push(eodTask);
  }

  // 2. Look for items left in progress
  for (const sodTask of sod) {
    const foundInEod = eod.some(eodTask => eodTask.title.toLowerCase() === sodTask.title.toLowerCase());
    const foundInBlocked = blocked.some(bTask => bTask.title.toLowerCase() === sodTask.title.toLowerCase());

    if (!foundInEod && !foundInBlocked) {
      inProgress.push(sodTask);
    }
  }

  // Only pass forward if there's tracking activity for this worker today
  if (completed.length > 0 || inProgress.length > 0 || blocked.length > 0) {
    finalEmployees[employee] = { completed, inProgress, blocked };
  }
}

/* =========================================================
   SORTING EMPLOYEES
========================================================= */
const sortedEmployees = Object.keys(finalEmployees).sort((a, b) =>
  a.trim().toLowerCase().localeCompare(b.trim().toLowerCase())
);

/* =========================================================
   ADAPTIVE CARD GENERATION
========================================================= */
const cardBody = [];

// Header Info
cardBody.push({ type: "TextBlock", text: `📋 ${SUMMARY_TITLE}`, weight: "Bolder", size: "Large", wrap: true });
cardBody.push({ type: "TextBlock", text: `📅 ${getSummaryDisplayDate()}`, spacing: "Small", wrap: true });
cardBody.push({ type: "TextBlock", text: "", separator: true });

if (sortedEmployees.length === 0) {
  cardBody.push({ type: "TextBlock", text: "No shift updates found for today.", wrap: true });
}

// Helper text line builder
function buildTaskLines(tasks) {
  let lines = [];
  for (let i = 0; i < tasks.length; i++) {
    const task = tasks[i];
    let line = `${i + 1}. ${task.title}`;
    if (task.dueDate) line += ` | Due: ${task.dueDate}`;
    if (task.delayed) line += ` ⚠️`;
    if (task.notes) line += `\n   ↳ *Notes: ${task.notes}*`;
    lines.push(line);
  }
  return lines.join('\n\n');
}

/* =========================================================
   EMPLOYEE RENDERING
========================================================= */
for (const employee of sortedEmployees) {
  const { completed, inProgress, blocked } = finalEmployees[employee];

  cardBody.push({ type: "TextBlock", text: `👤 ${employee}`, weight: "Bolder", size: "Medium", spacing: "Large", wrap: true });

  // --- EOD UPDATES SECTION ---
  if (completed.length || inProgress.length) {
    cardBody.push({ type: "TextBlock", text: "🔄 EOD Updates", weight: "Bolder", color: "Accent", spacing: "Small", wrap: true });

    if (completed.length) {
      cardBody.push({ type: "TextBlock", text: "  ✅ *Completed Tasks*:", spacing: "Small", wrap: true });
      cardBody.push({ type: "TextBlock", text: buildTaskLines(completed), wrap: true, spacing: "Small" });
    }

    if (inProgress.length) {
      cardBody.push({ type: "TextBlock", text: "  ⏳ *In Progress Tasks*:", spacing: "Small", wrap: true });
      cardBody.push({ type: "TextBlock", text: buildTaskLines(inProgress), wrap: true, spacing: "Small" });
    }
  }

  // --- BLOCKED TASKS SECTION ---
  if (blocked.length) {
    cardBody.push({ type: "TextBlock", text: "🚫 Blocked Tasks", weight: "Bolder", color: "Attention", spacing: "Medium", wrap: true });
    cardBody.push({ type: "TextBlock", text: buildTaskLines(blocked), wrap: true, spacing: "Small" });
  }
}

/* =========================================================
   FINAL OUTPUT PAYLOAD
========================================================= */
const payload = {
  subject: SUMMARY_TITLE,
  body: { contentType: "html", content: '<attachment id="1"></attachment>' },
  attachments: [
    {
      id: "1",
      contentType: "application/vnd.microsoft.card.adaptive",
      contentUrl: null,
      content: JSON.stringify({
        type: "AdaptiveCard",
        version: "1.4",
        $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
        body: cardBody
      })
    }
  ]
};

return [{ json: { payload: JSON.stringify(payload) } }];
